/*
 * System validation: Protocol Engines driven by Ibex (cocotb: test_sysval_pe_uart).
 *
 * Firmware loads the UART programs from examples/pe/uart.pe (uart_prog.h,
 * generated by peemu), runs TX on engine 0 (pad 16 = uo_out[0]) and RX on
 * engine 1 (pad 0 = ui_in[0]), and echoes every byte the host sends until a
 * '\n'. 8 ticks per bit, CLKDIV INT = 4: 32 system clocks per bit.
 *
 * Also checks on the way:
 *   - register readback of the per-engine and shared registers it writes;
 *   - the RX-not-empty interrupt line reaches Ibex (mip, fast IRQ 24 + 1);
 *   - start of both engines in one ENGINE_CTRL write;
 *   - SAFE_STATE releases the engine pads (owner NONE) at the end.
 * Register offsets: docs/pe_isa.md section 6.
 */
#include <stdint.h>

#include "csr.h"
#include "fw.h"
#include "mmio.h"
#include "platform.h"
#include "uart_prog.h"

#define PE(off)          (FW_PE_BASE + (off))
#define ENG(n, off)      PE(0x100u * (n) + (off))
#define CTRL      0x00u
#define CLKDIV    0x04u
#define EXECCTRL  0x08u
#define SHIFTCTRL 0x0Cu
#define PINCTRL   0x10u
#define ASSIST    0x14u
#define TIMING    0x1Cu
#define TXF       0x24u
#define RXF       0x28u
#define STATUS    0x2Cu
#define IMEM(i)          PE(0x400u + 4u * (i))
#define IRQ_EN           PE(0x50Cu)
#define ENGINE_CTRL      PE(0x510u)
#define SAFE_STATE       PE(0x514u)
#define GPIO_OUT_SET     PE(0x528u)
#define PAD_OWNER(p)     PE(0x540u + 4u * ((p) - 8u))
#define OWNER_CPU  4u
#define OWNER_NONE 7u

#define TX_ORIGIN 0u
#define RX_ORIGIN 8u
#define TX_PAD    16u                   /* uo_out[0] */
#define RX_PAD    0u                    /* ui_in[0] */
#define DIV_INT   4u

#define CHECK(n, cond) do { if (!(cond)) return (n); } while (0)

static uint32_t rx_level(void) { return mmio_read32(ENG(1, STATUS)) >> 12 & 0xFu; }
static uint32_t tx_level(void) { return mmio_read32(ENG(0, STATUS)) >> 8 & 0xFu; }

static int load(void)
{
    for (unsigned i = 0; i < UART_TX_LEN; i++)
        mmio_write32(IMEM(TX_ORIGIN + i), uart_tx_program[i]);
    for (unsigned i = 0; i < UART_RX_LEN; i++)
        mmio_write32(IMEM(RX_ORIGIN + i), uart_rx_program[i]);
    for (unsigned i = 0; i < UART_RX_LEN; i++)
        if (mmio_read32(IMEM(RX_ORIGIN + i)) != uart_rx_program[i])
            return 1;

    /* TX: out pins and side-set on TX_PAD */
    uint32_t tx_pin = TX_PAD | (1u << 5) | (TX_PAD << 19);       /* OUT_BASE, OUT_COUNT 1, SIDE_BASE */
    mmio_write32(ENG(0, CLKDIV), DIV_INT << 16);
    mmio_write32(ENG(0, EXECCTRL), UART_TX_EXECCTRL | TX_ORIGIN << 24);
    mmio_write32(ENG(0, SHIFTCTRL), UART_TX_SHIFTCTRL);
    mmio_write32(ENG(0, PINCTRL), tx_pin);
    mmio_write32(ENG(0, ASSIST), UART_TX_ASSIST);
    mmio_write32(ENG(0, TIMING), UART_TX_TIMING);
    if (mmio_read32(ENG(0, PINCTRL)) != tx_pin)
        return 2;

    /* RX: in pins and jmp pin on RX_PAD, frame-start sync on the falling edge */
    mmio_write32(ENG(1, CLKDIV), DIV_INT << 16);
    mmio_write32(ENG(1, EXECCTRL), UART_RX_EXECCTRL | RX_PAD << 10 | RX_ORIGIN << 24);
    mmio_write32(ENG(1, SHIFTCTRL), UART_RX_SHIFTCTRL);
    mmio_write32(ENG(1, PINCTRL), RX_PAD << 24);
    mmio_write32(ENG(1, ASSIST), UART_RX_ASSIST);
    mmio_write32(ENG(1, TIMING), UART_RX_TIMING);
    if (mmio_read32(ENG(1, EXECCTRL)) != (UART_RX_EXECCTRL | RX_PAD << 10 | RX_ORIGIN << 24))
        return 3;

    /* pad: take it as CPU GPIO at idle high, then hand it to engine 0 */
    mmio_write32(PAD_OWNER(TX_PAD), OWNER_CPU);
    mmio_write32(GPIO_OUT_SET, 1u << (TX_PAD - 8u));
    mmio_write32(PAD_OWNER(TX_PAD), 0u);
    if (mmio_read32(PAD_OWNER(TX_PAD)) != 0u)
        return 4;
    return 0;
}

int main(void)
{
    int r = load();
    if (r)
        return r;

    mmio_write32(IRQ_EN, 1u << (8 + 1));                 /* engine 1 RX not empty */
    mmio_write32(ENGINE_CTRL, 0x3u | 0x3u << 4 | 0x3u << 8);
    CHECK(5, (mmio_read32(ENGINE_CTRL) & 0xFu) == 0x3u);
    CHECK(6, !(csr_read(mip) & (1u << 25)));             /* nothing received yet */

    mmio_write32(FW_SYSCTRL_SCRATCH, 0x2u);              /* tell the host: ready (even = no result) */

    unsigned n = 0;
    uint32_t t = mmio_read32(FW_SYSCTRL_CYCLE);
    for (;;) {
        while (rx_level() == 0) {
            if (mmio_read32(FW_SYSCTRL_CYCLE) - t > 400000u)
                return 7;                                /* host stopped sending */
        }
        CHECK(8, csr_read(mip) & (1u << 25));            /* RX IRQ line is pending */
        uint32_t b = mmio_read32(ENG(1, RXF)) >> 24;     /* bytes land in [31:24] */
        while (tx_level() >= 2u) { }
        mmio_write32(ENG(0, TXF), b);
        n++;
        t = mmio_read32(FW_SYSCTRL_CYCLE);
        if (b == '\n')
            break;
    }
    CHECK(9, !(mmio_read32(ENG(1, STATUS)) & (3u << 17)));  /* no TXOVF/RXUNF */
    CHECK(10, !(mmio_read32(PE(0x500u)) & (1u << 5)));      /* no framing error flag */

    while (tx_level() != 0u) { }                         /* last byte pulled ... */
    uint32_t t0 = mmio_read32(FW_SYSCTRL_CYCLE);
    while (mmio_read32(FW_SYSCTRL_CYCLE) - t0 < 12u * 8u * DIV_INT) { }   /* ... and sent */

    mmio_write32(SAFE_STATE, 0x5AFEu);
    CHECK(11, (mmio_read32(ENGINE_CTRL) & 0xFu) == 0u);
    CHECK(12, mmio_read32(PAD_OWNER(TX_PAD)) == OWNER_NONE);
    CHECK(13, mmio_read32(PAD_OWNER(23u)) == 5u);       /* host MISO stays with the system */
    return n == 0 ? 14 : 0;
}
